                'content' => '"{\\"intro\\":{\\"en\\":\\"<p>Official examination policy guidelines and grading evaluation criteria at Digital University of Cambodia.<\\\\\\/p>\\",\\"km\\":\\"<p>\\\\u1782\\\\u17c4\\\\u179b\\\\u1780\\\\u17b6\\\\u179a\\\\u178e\\\\u17cd\\\\u178e\\\\u17c2\\\\u1793\\\\u17b6\\\\u17c6\\\\u179f\\\\u17d2\\\\u178f\\\\u17b8\\\\u1796\\\\u17b8\\\\u1780\\\\u17b6\\\\u179a\\\\u1794\\\\u17d2\\\\u179a\\\\u17a1\\\\u1784 \\\\u1793\\\\u17b7\\\\u1784\\\\u179b\\\\u1780\\\\u17d2\\\\u1781\\\\u178e\\\\u17c8\\\\u179c\\\\u17b7\\\\u1793\\\\u17b7\\\\u1785\\\\u17d2\\\\u1786\\\\u17d0\\\\u1799\\\\u179c\\\\u17b6\\\\u1799\\\\u178f\\\\u1798\\\\u17d2\\\\u179b\\\\u17c3\\\\u1796\\\\u17b7\\\\u1793\\\\u17d2\\\\u1791\\\\u17bb\\\\u1795\\\\u17d2\\\\u179b\\\\u17bc\\\\u179c\\\\u1780\\\\u17b6\\\\u179a\\\\u1793\\\\u17c5\\\\u179f\\\\u17b6\\\\u1780\\\\u179b\\\\u179c\\\\u17b7\\\\u1791\\\\u17d2\\\\u1799\\\\u17b6\\\\u179b\\\\u17d0\\\\u1799\\\\u178c\\\\u17b8\\\\u1787\\\\u17b8\\\\u1790\\\\u179b\\\\u1780\\\\u1798\\\\u17d2\\\\u1796\\\\u17bb\\\\u1787\\\\u17b6\\\\u17d4<\\\\\\/p>\\"},\\"breakdown\\":[{\\"criteria\\":{\\"en\\":\\"Attendance and Participation\\",\\"km\\":\\"\\\\u179c\\\\u178f\\\\u17d2\\\\u178f\\\\u1798\\\\u17b6\\\\u1793 \\\\u1793\\\\u17b7\\\\u1784\\\\u1780\\\\u17b6\\\\u179a\\\\u1785\\\\u17bc\\\\u179b\\\\u179a\\\\u17bd\\\\u1798\\"},\\"percentage\\":\\"10%\\"},{\\"criteria\\":{\\"en\\":\\"Quizzes and Assignments\\",\\"km\\":\\"\\\\u1780\\\\u17b6\\\\u179a\\\\u1794\\\\u17d2\\\\u179a\\\\u17a1\\\\u1784\\\\u1781\\\\u17d2\\\\u179b\\\\u17b8 \\\\u1793\\\\u17b7\\\\u1784\\\\u1780\\\\u17b7\\\\u1785\\\\u17d2\\\\u1785\\\\u1780\\\\u17b6\\\\u179a\\\\u1795\\\\u17d2\\\\u1791\\\\u17c7\\"},\\"percentage\\":\\"15%\\"},{\\"criteria\\":{\\"en\\":\\"Midterm Examination\\",\\"km\\":\\"\\\\u1780\\\\u17b6\\\\u179a\\\\u1794\\\\u17d2\\\\u179a\\\\u17a1\\\\u1784\\\\u1796\\\\u17b6\\\\u1780\\\\u17cb\\\\u1780\\\\u178e\\\\u17d2\\\\u178f\\\\u17b6\\\\u179b\\\\u1786\\\\u1798\\\\u17b6\\\\u179f\\"},\\"percentage\\":\\