                'content' => '"{\\"custom_sections\\":[{\\"title\\":{\\"en\\":\\"Kampong Speo\\",\\"km\\":\\"\\\\u1780\\\\u17c6\\\\u1796\\\\u1784\\\\u17cb\\\\u179f\\\\u17d2\\\\u1796\\\\u17ba\\"},\\"content\\":{\\"en\\":\\"<p>Every degree certificate issued by the Digital University of Cambodia features a unique QR Code and serial number for immediate verification. This ensures the integrity of our academic credentials and allows employers to easily authenticate the qualifications of our graduates through our official verification system.<\\\\\\/p>\\",\\"km\\":\\"<p>\\\\u179c\\\\u17b7\\\\u1789\\\\u17d2\\\\u1789\\\\u17b6\\\\u1794\\\\u1793\\\\u1794\\\\u178f\\\\u17d2\\\\u179a\\\\u179f\\\\u1789\\\\u17d2\\\\u1789\\\\u17b6\\\\u1794\\\\u178f\\\\u17d2\\\\u179a\\\\u1793\\\\u17b8\\\\u1798\\\\u17bd\\\\u1799\\\\u17d7\\\\u178a\\\\u17c2\\\\u179b\\\\u1785\\\\u17c1\\\\u1789\\\\u178a\\\\u17c4\\\\u1799\\\\u179f\\\\u17b6\\\\u1780\\\\u179b\\\\u179c\\\\u17b7\\\\u1791\\\\u17d2\\\\u1799\\\\u17b6\\\\u179b\\\\u17d0\\\\u1799\\\\u178c\\\\u17b8\\\\u1787\\\\u17b8\\\\u1790\\\\u179b\\\\u1780\\\\u1798\\\\u17d2\\\\u1796\\\\u17bb\\\\u1787\\\\u17b6\\\\u1798\\\\u17b6\\\\u1793\\\\u179b\\\\u17c1\\\\u1781\\\\u1780\\\\u17bc\\\\u178a QR \\\\u1793\\\\u17b7\\\\u1784\\\\u179b\\\\u17c1\\\\u1781\\\\u179f\\\\u17ca\\\\u17c1\\\\u179a\\\\u17b8\\\\u178f\\\\u17c2\\\\u1798\\\\u17bd\\\\u1799\\\\u1782\\\\u178f\\\\u17cb\\\\u179f\\\\u1798\\\\u17d2\\\\u179a\\\\u17b6\\\\u1794\\\\u17cb\\\\u1780\\\\u17b6\\\\u179a\\\\u1795\\\\u17d2\\\\u1791\\\\u17c0\\\\u1784\\\\u1795\\\\u17d2\\\\u1791\\\\u17b6\\\\u178f\\\\u17cb\\\\u1797\\\\u17d2\\\\u179b\\\\u17b6\\\\u1798\\\\u17d7\\\\u17d4 \\\\u1793\\\\u17c1\\\\u17c7\\\\u1792\\\\u17b6\\\\u1793\\\\u17b6\\\\u1793\\\\u17bc\\\\u179c\\\\u1797\\\\u17b6\\\\u1796\\\\u179f\\\\u17bb\\\\u1785\\\\u179a\\\\u17b7\\\\u178f\\\\u1793\\\\u17c3\\\\u179b\\\\u17b7\\\\u1781\\\\u17b7\\\\u178f\\\\u1794\\\\u1789\\\\u17d2\\\\u1787\\\\u17b6\\\\u1780\\\\u17cb\\\\u1780\\\\u17b6\\\\u179a\\\\u179f\\\\u17b7\\\\u1780\\\\u17d2\